/* ── Result banner ──────────────────────────────────────────── */
.result-banner {
  display: none;
  margin-top: 24px;
  padding: 14px 18px;
  border-radius: var(--radius-md);
  font-size: 14px;
  font-weight: 500;
  line-height: 1.5;
}

.result-banner.visible {
  display: block;
}

.result-banner.success {
  background: #ecfdf5;
  color: #065f46;
  border: 1.5px solid #6ee7b7;
}

.result-banner.partial {
  background: #fefce8;
  color: #854d0e;
  border: 1.5px solid #fde68a;
}

.result-banner.zero {
  background: #fff1f2;
  color: #9f1239;
  border: 1.5px solid #fda4af;
}

.result-banner strong {
  display: block;
  font-size: 15px;
  margin-bottom: 2px;
}

@media (max-width: 480px) {
  .quiz-card {
    padding: 24px 18px;
  }
}

const quizData = [
  {
    id: "q1",
    number: "Question 1",
    question: "Which of the following are compiled languages?",
    help: "Select all that apply — there may be more than one correct answer.",
    options: [
      { id: "q1a", label: "C++", correct: true },
      { id: "q1b", label: "Python", correct: false },
      { id: "q1c", label: "Rust", correct: true },
      { id: "q1d", label: "Ruby", correct: false },
    ],
  },
  {
    id: "q2",
    number: "Question 2",
    question: "Which languages are primarily used for front-end web development?",
    options: [
      { id: "q2a", label: "JavaScript", correct: true },
      { id: "q2b", label: "TypeScript", correct: true },
      { id: "q2c", label: "Go", correct: false },
      { id: "q2d", label: "CSS", correct: true },
    ],
  },
  {
    id: "q3",
    number: "Question 3",
    question: "Which of the following are statically typed languages?",
    options: [
      { id: "q3a", label: "Java", correct: true },
      { id: "q3b", label: "TypeScript", correct: true },
      { id: "q3c", label: "PHP", correct: false },
      { id: "q3d", label: "Kotlin", correct: true },
    ],
  },
];

function QuizApp() {
  const totalQuestions = quizData.length;
  let answeredCount = 0;

  // Track selections: { questionId: Set<optionId> }
  const selections = {};
  quizData.forEach((q) => (selections[q.id] = new Set()));

  function countAnswered() {
    return quizData.filter((q) => selections[q.id].size > 0).length;
  }

  function updateProgress() {
    answeredCount = countAnswered();
    const pct = Math.round((answeredCount / totalQuestions) * 100);
    document.getElementById("progress-fill").style.width = pct + "%";
    document.getElementById("progress-label").textContent =
      answeredCount + " / " + totalQuestions + " answered";
  }

  function renderQuestion(q) {
    const isFirst = q === quizData[0];
    const fieldEl = document.createElement("div");
    fieldEl.className = "form-field";
    fieldEl.id = "field-" + q.id;

    const numberEl = document.createElement("span");
    numberEl.className = "form-field__number";
    numberEl.textContent = q.number;

    const labelEl = document.createElement("p");
    labelEl.className = "form-field__label";
    labelEl.textContent = q.question;

    fieldEl.appendChild(numberEl);
    fieldEl.appendChild(labelEl);

    if (isFirst && q.help) {
      const helpEl = document.createElement("p");
      helpEl.className = "form-field__help";
      helpEl.innerHTML = `
        <svg width="14" height="14" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
          <circle cx="10" cy="10" r="9" stroke="currentColor" stroke-width="1.8"/>
          <path d="M10 9v5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/>
          <circle cx="10" cy="6.5" r="0.75" fill="currentColor"/>
        </svg>
        ${q.help}`;
      fieldEl.appendChild(helpEl);
    }

    const optionsEl = document.createElement("div");
    optionsEl.className = "options";
    optionsEl.setAttribute("role", "group");
    optionsEl.setAttribute("aria-label", q.question);

    q.options.forEach((opt) => {
      const label = document.createElement("label");
      label.className = "option";
      label.htmlFor = opt.id;

      const input = document.createElement("input");
      input.type = "checkbox";
      input.id = opt.id;
      input.name = q.id;
      input.value = opt.id;

      input.addEventListener("change", () => {
        if (input.checked) {
          selections[q.id].add(opt.id);
          label.classList.add("is-checked");
        } else {
          selections[q.id].delete(opt.id);
          label.classList.remove("is-checked");
        }
        updateProgress();
        hideBanner();
      });

      const span = document.createElement("span");
      span.className = "option-text";
      span.textContent = opt.label;

      label.appendChild(input);
      label.appendChild(span);
      optionsEl.appendChild(label);
    });

    fieldEl.appendChild(optionsEl);
    return fieldEl;
  }

  function hideBanner() {
    const banner = document.getElementById("result-banner");
    banner.className = "result-banner";
    banner.innerHTML = "";
  }

  function handleSubmit() {
    let totalCorrect = 0;

    quizData.forEach((q) => {
      const correctIds = new Set(
        q.options.filter((o) => o.correct).map((o) => o.id)
      );
      const selected = selections[q.id];

      // Question is fully correct when selected set equals correct set
      const isCorrect =
        selected.size === correctIds.size &&
        [...selected].every((id) => correctIds.has(id));

      if (isCorrect) totalCorrect++;
    });

    const banner = document.getElementById("result-banner");
    banner.classList.add("visible");

    if (totalCorrect === totalQuestions) {
      banner.classList.add("success");
      banner.innerHTML = `<strong>🎉 Perfect score!</strong>You got all ${totalQuestions} questions right. Well done!`;
    } else if (totalCorrect > 0) {
      banner.classList.add("partial");
      banner.innerHTML = `<strong>Almost there!</strong>You got ${totalCorrect} out of ${totalQuestions} questions fully correct. Review your answers and try again.`;
    } else {
      banner.classList.add("zero");
      banner.innerHTML = `<strong>Keep studying!</strong>None of the questions were fully correct. Give it another shot!`;
    }

    banner.scrollIntoView({ behavior: "smooth", block: "nearest" });
  }

  function mount(rootEl) {
    // Header
    const header = document.createElement("header");
    header.className = "quiz-header";
    header.innerHTML = `
      <span class="badge">Knowledge Check</span>
      <h1>Computer Languages Quiz</h1>
      <p>Select all answers that apply for each question.</p>`;
    rootEl.appendChild(header);

    // Card
    const card = document.createElement("div");
    card.className = "quiz-card";

    // Progress
    const progressWrap = document.createElement("div");
    progressWrap.className = "progress-bar-wrap";
    progressWrap.innerHTML = `
      <div class="progress-bar-track">
        <div class="progress-bar-fill" id="progress-fill" style="width:0%"></div>
      </div>
      <span class="progress-label" id="progress-label">0 / ${totalQuestions} answered</span>`;
    card.appendChild(progressWrap);

    // Form fields
    const form = document.createElement("form");
    form.id = "quiz-form";
    form.noValidate = true;
    form.addEventListener("submit", (e) => {
      e.preventDefault();
      handleSubmit();
    });

    const fieldsWrap = document.createElement("div");
    fieldsWrap.className = "form-fields";

    quizData.forEach((q, i) => {
      fieldsWrap.appendChild(renderQuestion(q));
      if (i < quizData.length - 1) {
        const div = document.createElement("div");
        div.className = "divider";
        fieldsWrap.appendChild(div);
      }
    });

    form.appendChild(fieldsWrap);

    // Submit row
    const submitRow = document.createElement("div");
    submitRow.className = "submit-row";
    const btn = document.createElement("button");
    btn.type = "submit";
    btn.className = "btn-submit";
    btn.innerHTML = `Submit Quiz <svg width="16" height="16" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><path d="M4 10h12M12 6l4 4-4 4" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
    submitRow.appendChild(btn);
    form.appendChild(submitRow);

    // Result banner
    const banner = document.createElement("div");
    banner.id = "result-banner";
    banner.className = "result-banner";
    form.appendChild(banner);

    card.appendChild(form);
    rootEl.appendChild(card);
  }

  return { mount };
}

document.addEventListener("DOMContentLoaded", () => {
  const root = document.getElementById("app");
  QuizApp().mount(root);
});

